                        transitionIndex: 0,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
            if event == .again {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.idle)],
                        transitionIndex: 1,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
        default:
            break
        }
        return nil
    }

